SELECT DISTINCT ?item ?matchedLabel ?en ?zh ?description ?kind WHERE {
          VALUES ?matchedLabel { "Cauchy's integral formula"@en "Euler method"@en "Lagrange multiplier"@en "Newton's method"@en "Runge-Kutta method"@en "analytic function"@en "binomial coefficient"@en "bipartite graph"@en "bisection method"@en "cauchy's integral formula"@en "combination"@en "combinatorics"@en "complex analysis"@en "concave function"@en "condition number"@en "conformal mapping"@en "connected graph"@en "constraint"@en "contour integral"@en "contraction mapping"@en "convex function"@en "convex set"@en "covering space"@en "critical point"@en "cycle"@en "dependent function type"@en "dependent pair"@en "dependent type"@en "dependent type theory"@en "directed graph"@en "edge"@en "elaboration"@en "euler method"@en "extrapolation"@en "finite difference"@en "finite element method"@en "fixed point"@en "generating function"@en "graph"@en "graph coloring"@en "harmonic function"@en "holomorphic function"@en "inclusion-exclusion principle"@en "inductive type"@en "integer programming"@en "interactive theorem prover"@en "interpolation"@en "lagrange multiplier"@en "linear programming"@en "matching"@en "meromorphic function"@en "newton's method"@en "numerical analysis"@en "numerical integration"@en "objective function"@en "optimization"@en "path"@en "permutation"@en "pigeonhole principle"@en "planar graph"@en "pole"@en "proof assistant"@en "proof state"@en "proof term"@en "recurrence relation"@en "residue"@en "residue theorem"@en "rounding error"@en "runge-kutta method"@en "saddle point"@en "simplifier"@en "singularity"@en "spanning tree"@en "stationary point"@en "tactic"@en "tactic proof"@en "theorem prover"@en "tree"@en "truncation error"@en "type class"@en "type theory"@en "typeclass inference"@en "undirected graph"@en "unification"@en "vertex"@en }
          ?item (rdfs:label|skos:altLabel) ?matchedLabel.
          OPTIONAL { ?item rdfs:label ?en. FILTER(LANG(?en)="en") }
          OPTIONAL { ?item rdfs:label ?zh. FILTER(LANG(?zh) IN ("zh-hans","zh-cn","zh")) }
          OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
          OPTIONAL { ?item wdt:P31 ?kind }
        }
